const recordUI={tab:'minutes',language:'original',compare:true,selected:-1,query:'',transcriptQuery:'',split:42};
const languageUI={source:'auto',target:'zh-Hans',mode:'both'};
const languageOptions=[['auto','自动识别'],['zh-Hans','简体中文'],['zh-Hant','繁體中文'],['en','English'],['ja','日本語'],['ko','한국어'],['fr','Français'],['de','Deutsch'],['es','Español'],['pt','Português'],['it','Italiano'],['ru','Русский'],['ar','العربية'],['hi','हिन्दी'],['vi','Tiếng Việt'],['th','ไทย'],['id','Bahasa Indonesia'],['tr','Türkçe'],['nl','Nederlands'],['pl','Polski'],['uk','Українська'],['sv','Svenska'],['fi','Suomi'],['el','Ελληνικά'],['he','עברית'],['bn','বাংলা'],['ta','தமிழ்'],['ms','Bahasa Melayu'],['fa','فارسی'],['ur','اردو']];
function languageName(id){return languageOptions.find(x=>x[0]===id)?.[1]||id}
function languagePair(){return languageName(languageUI.source)+' → '+languageName(languageUI.target)}
function languageSelect(key,label){return `<label class="language-select">${label}<select aria-label="${label}" data-language="${key}">${languageOptions.filter(x=>key==='source'||x[0]!=='auto').map(([id,name])=>`<option value="${id}" ${languageUI[key]===id?'selected':''}>${name}</option>`).join('')}</select></label>`}
function languagePanel(){return `<h3>语言与翻译</h3><div class="language-pair">${languageSelect('source','原始语言')}<span>→</span>${languageSelect('target','翻译语言')}</div><div class="setting-row"><span>字幕内容</span><div class="segmented">${[['both','双语'],['translation','仅译文'],['original','仅原文']].map(([v,l])=>`<button data-language-mode="${v}" aria-pressed="${languageUI.mode===v}" class="${languageUI.mode===v?'active':''}">${l}</button>`).join('')}</div></div>${row('阅读顺序','',segmented('originalFirst',[[false,'译文在上'],[true,'原文在上']]))}<p class="language-note">语言列表随连接的服务提供。下方为英文 → 中文字幕示例。</p>`}
const demoRecord={title:'从源代码到 LLVM IR：理解 Clang 前端',date:'示例记录 · 技术分享',duration:720,example:true,summary:'围绕编译器前端的数据流，梳理 Parser、AST 与 Sema 的职责，并解释语义分析如何衔接 LLVM IR 和优化阶段。',lines:[
{time:0,speaker:'讲者',zh:'今天我们从一段 C++ 源代码出发，看看 Clang 前端如何理解程序。这里主要区分三个概念：解析器、抽象语法树，以及语义分析。它们相互协作，但解决的是不同的问题。',en:'Today we will start with a piece of C++ source code and look at how the Clang front end understands a program. We will distinguish three concepts: the parser, the abstract syntax tree, and semantic analysis. They work together, but solve different problems.'},
{time:152,speaker:'讲者',zh:'解析器识别代码的语法结构，并在语义分析的协作下构建 AST。AST 用节点表达声明、表达式和语句。拥有语法结构并不意味着程序一定有效，还需要检查类型与名称的含义。',en:'The parser recognizes the syntactic structure of the code and builds an AST in cooperation with semantic analysis. The AST represents declarations, expressions, and statements as nodes. Having a syntactic structure does not mean a program is valid; types and the meaning of names still need to be checked.'},
{time:328,speaker:'讲者',zh:'Sema 参与名称查找、类型检查和诊断。例如，表达式中的类型不匹配时，需要结合上下文判断问题，并给出诊断信息。为了理解实现，可以把语法结构和语义约束分开学习，但不要误以为它们是完全隔离的两个处理步骤。',en:'Sema participates in name lookup, type checking, and diagnostics. For example, when the types in an expression do not match, the context is needed to understand the problem and produce a diagnostic. It is useful to study syntax and semantic constraints separately, but they should not be mistaken for two entirely isolated processing steps.'},
{time:511,speaker:'讲者',zh:'通过前端检查后，代码生成阶段将程序转换为 LLVM IR。后续优化围绕这个中间表示展开。今天的重点是理解各组件的职责与衔接；具体优化算法可以在后续课程中展开。',en:'After front-end checks, code generation lowers the program to LLVM IR. Subsequent optimization operates on that intermediate representation. Today the focus is on component responsibilities and how they connect; specific optimization algorithms can be explored in a later session.'}
],topics:[['前端的整体职责','先建立源代码到中间表示的整体视角。',0],['Parser 与 AST','结构识别与树形表示；语法结构不等于语义有效。',1],['Sema 与语义约束','名称查找、类型检查和诊断需要结合上下文。',2],['LLVM IR 与后续优化','前端与优化通过中间表示衔接。',3]]};
function activeRecord(){return state.selectedRecord==='demo'?demoRecord:state.records[state.selectedRecord]}
function recordCards(){const records=[{r:demoRecord,id:'demo'},...state.records.map((r,id)=>({r,id}))];const filtered=records.filter(({r})=>(r.title+' '+(r.summary||'')).toLowerCase().includes(recordUI.query.toLowerCase()));return `<div class="document-list">${filtered.map(({r,id})=>`<button class="document-card" data-record="${id}"><div class="document-icon">▤</div><div class="document-info"><div class="document-title"><strong>${esc(r.title)}</strong><span class="document-status">${r.example?'示例 · 已整理':r.note?'已整理':'待整理'}</span></div><p>${esc(r.summary||r.lines[0]?.zh||'暂无摘要')}</p><small>${esc(r.date)} <span>·</span> ${clockText(r.duration)} <span>·</span> ${r.example?'技术分享':'字幕记录'}</small></div><span class="document-arrow">↗</span></button>`).join('')||'<div class="records-empty">没有匹配的记录</div>'}</div>`}
function sourceButton(i,label='查看原文'){return `<button class="source-ref" data-source="${i}" aria-label="${label} ${clockText(activeRecord().lines[i].time)}">↗ ${clockText(activeRecord().lines[i].time)}</button>`}
function recordTranscript(r,compact=false){return `<div class="transcript-reader ${compact?'compact':''}">${r.lines.map((x,i)=>`<article id="source-${i}" class="transcript-paragraph ${recordUI.selected===i?'selected':''}"><div class="paragraph-meta"><span>${esc(x.speaker||'说话人 1')}</span><button data-source="${i}">${clockText(x.time)}</button><button class="line-edit" data-edit-line="${i}" aria-label="编辑第 ${i+1} 段">✎</button></div>${recordUI.language!=='translation'?`<p class="original-text" lang="en">${esc(x.en)}</p>`:''}${recordUI.language!=='original'?`<p class="translation-text" lang="zh">${esc(x.zh)}</p>`:''}</article>`).join('')}</div>`}
function recordSummary(r){if(!r.example)return `<div class="document-empty"><span>✧</span><h2>原文已保存</h2><p>这条记录尚未生成总结与纪要。</p><button class="small" data-record-tab="transcript">阅读原文与翻译 →</button></div>`;return `<div class="summary-lead"><span class="document-kicker">SUMMARY</span><h2>理解前端各组件如何协作</h2><p>${esc(r.summary)}</p></div><div class="takeaways"><h3>核心要点</h3>${[['AST 表达程序结构，不能单凭语法判断程序有效。',1],['Sema 负责语义约束，并与解析过程协作。',2],['LLVM IR 连接前端代码生成与后续优化。',3]].map(([t,i])=>`<div><p>${t}</p>${sourceButton(i)}</div>`).join('')}</div><section class="record-section"><h3>从源代码到优化</h3><div class="flow-diagram"><span>源代码</span><b>→</b><span>Parser ↔ Sema<small>构建与检查 AST</small></span><b>→</b><span>代码生成<small>LLVM IR</small></span><b>→</b><span>优化</span></div><p class="figure-caption">概念流程 · ${sourceButton(1)} ${sourceButton(3)}</p></section><section class="record-section"><h3>继续阅读</h3><p>按议题查看课程笔记，或沿时间线回到具体段落。</p><button class="small" data-record-tab="minutes">阅读纪要 →</button></section>`}
function recordMinutes(r){if(!r.example)return recordSummary(r);return `<div class="minutes-document"><header><h2>${esc(r.title)}</h2><div class="document-byline">讲者 · 技术分享</div><p><span class="inline-label">主题摘要</span>${esc(r.summary)}</p></header><section class="minutes-conclusions"><h3>核心结论</h3><ul><li>AST 描述程序的结构，语义有效性需要进一步检查。${sourceButton(1)}</li><li>Parser 与 Sema 协作完成前端分析，不应理解为两个完全隔离的步骤。${sourceButton(2)}</li><li>代码生成将程序转换为 LLVM IR，后续优化围绕中间表示展开。${sourceButton(3)}</li></ul></section><section class="minutes-table"><h3>前端组件的职责</h3><table><thead><tr><th>组件</th><th>主要职责</th><th>与其他组件的关系</th></tr></thead><tbody><tr><td>Parser</td><td>识别源代码的语法结构</td><td>与语义分析协作构建 AST ${sourceButton(1)}</td></tr><tr><td>AST</td><td>表示声明、表达式与语句</td><td>承载程序结构，供语义检查与后续处理使用 ${sourceButton(1)}</td></tr><tr><td>Sema</td><td>名称查找、类型检查、诊断</td><td>结合上下文判断代码是否满足语义约束 ${sourceButton(2)}</td></tr></tbody></table></section><section class="minutes-insights"><h3>理解前端的两个关键点</h3><div><article><span>01 · 结构与含义</span><p>语法结构正确，不等于程序在语义上有效。</p>${sourceButton(1)}</article><article><span>02 · 协作关系</span><p>解析与语义分析相互协作，理解职责时也需要关注调用关系。</p>${sourceButton(2)}</article></div></section><section class="record-section"><h3>处理流程</h3><div class="flow-diagram"><span>源代码</span><b>→</b><span>Parser ↔ Sema<small>AST 构建与检查</small></span><b>→</b><span>代码生成<small>LLVM IR</small></span><b>→</b><span>优化</span></div>${sourceButton(3)}</section><section class="minutes-followup"><h3>后续主题</h3><p>本次聚焦组件职责与衔接，具体优化算法留待后续课程展开。${sourceButton(3)}</p></section></div>`}
function recordTimeline(r){const topics=r.topics||r.lines.map((x,i)=>['段落 '+(i+1),x.zh,i]);return `<div class="summary-lead"><span class="document-kicker">TIMELINE</span><h2>沿着内容的脉络回看</h2></div><div class="topic-timeline">${topics.map(([title,desc,i],j)=>`<button data-source="${i}"><span class="timeline-time">${clockText(r.lines[i].time)}<small>${clockText(j+1<topics.length?r.lines[topics[j+1][2]].time:r.duration)}</small></span><span class="timeline-dot"></span><span><strong>${esc(title)}</strong><p>${esc(desc)}</p></span><span>↗</span></button>`).join('')}</div>`}
function recordWorkspace(){const r=activeRecord();if(!r)return `${pageTitle('','记录','')}<div class="record-list-toolbar"><span>全部记录 <b>${state.records.length}</b> <small>另含 1 条设计示例</small></span><input class="search" id="record-search" aria-label="搜索记录" placeholder="搜索标题或摘要" value="${esc(recordUI.query)}"></div><div id="document-results">${recordCards()}</div>`;const tab=recordUI.tab,onlyText=tab==='transcript';return `<div class="record-detail"><header class="detail-header"><button class="back-record" data-action="back-records" aria-label="返回全部记录">‹</button><div><h1><button class="title-edit" data-edit-title>${esc(r.title)} <span>✎</span></button></h1><p><span>▦ ${esc(r.date)}</span><span>◷ ${clockText(r.duration)}</span><span>◉ 1 位讲者</span></p></div><div class="detail-actions"><span class="detail-example">${r.example?'设计示例':'已保存'}</span><button class="small" data-record-export>↓ 导出</button><button class="small" data-record-focus>${onlyText?'返回纪要':'展开原文'}</button></div></header><div class="record-desk ${recordUI.compare&&!onlyText?'split':''} ${onlyText?'text-focus':''}" style="--doc-width:${recordUI.split}%"><section class="document-pane"><div class="document-tabs" role="tablist" aria-label="记录视图">${[['overview','概览'],['minutes','纪要'],['timeline','时间线']].map(([id,l])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-record-tab="${id}">${l}</button>`).join('')}<button class="pane-tool" data-record-compare aria-label="${recordUI.compare?'收起原文对照':'打开原文对照'}">${recordUI.compare?'⇥':'⇤'}</button></div><div class="document-format">${templateSelector(r)}<button data-edit-minutes aria-label="编辑纪要">✎ 编辑</button><button data-record-copy aria-label="复制文档文本">⧉ 复制</button></div><div class="document-scroll">${recordDocument(r)}</div></section>${recordUI.compare||onlyText?`<div class="split-handle" role="separator" aria-label="调整纪要与原文宽度" aria-orientation="vertical" aria-valuenow="${recordUI.split}" tabindex="0"><span>Ⅱ</span></div><section class="reader-pane">${playerMarkup(r)}<div class="source-header"><div><h2>原文与翻译</h2><p>英语 → 简体中文 <span>·</span> ${r.lines.length} 段落</p></div>${readerLanguage()}</div><div class="transcript-tools"><label><span>⌕</span><input id="transcript-search" aria-label="搜索原文与译文" placeholder="搜索原文与译文" value="${esc(recordUI.transcriptQuery)}"></label><span id="match-count"></span></div><div id="detail-transcript">${recordTranscript(r,true)}</div>${questionMarkup(r)}</section>`:''}</div></div>`}
function readerLanguage(){return `<select aria-label="记录文本语言" data-record-language><option value="both" ${recordUI.language==='both'?'selected':''}>双语</option><option value="original" ${recordUI.language==='original'?'selected':''}>原文</option><option value="translation" ${recordUI.language==='translation'?'selected':''}>译文</option></select>`}
function legacyUsagePage(){return `${pageTitle('','用量','')}<div class="usage-toolbar"><span>设计示例 · 不代表真实账单</span><span>本地演示会话</span></div><div class="usage-metrics"><article><small>预计费用</small><strong>$0.00</strong><span>尚未接入计费数据</span></article><article><small>转录时长</small><strong>${Math.round(state.records.reduce((n,r)=>n+r.duration,0)/60)} <em>分钟</em></strong><span>来自本地演示记录</span></article><article><small>文本处理</small><strong>—</strong><span>翻译 · 总结 · 知识整理</span></article></div><div class="usage-panel"><h3>费用构成</h3><div class="usage-columns"><span>服务</span><span>用量</span><span>预计费用</span></div>${['语音转录','字幕翻译','总结与纪要','领域知识整理'].map(l=>`<div class="usage-columns"><span>${l}</span><span>待接入</span><span>—</span></div>`).join('')}<p>预计费用由实际使用量与服务单价计算；最终金额以服务商账单为准。</p></div>`}
function coreWorkspaceClick(b){const d=b.dataset;if(d.recordExport!==undefined){exportRecord();return true}if(d.recordCopy!==undefined){copyRecord();return true}if(d.recordFocus!==undefined){recordUI.tab=recordUI.tab==='transcript'?'minutes':'transcript';render();return true}if(d.recordTab){recordUI.tab=d.recordTab;render();return true}if(d.recordCompare!==undefined){recordUI.compare=!recordUI.compare;if(recordUI.tab==='transcript')recordUI.tab='minutes';render();return true}if(d.source!==undefined){recordUI.selected=Number(d.source);seekRecord(recordUI.selected);recordUI.transcriptQuery='';if(recordUI.tab!=='transcript')recordUI.compare=true;render();document.querySelector('#source-'+recordUI.selected)?.scrollIntoView({block:'nearest',behavior:'smooth'});return true}if(d.languageMode){languageUI.mode=d.languageMode;state.bilingual=d.languageMode==='both';render();return true}return false}
document.addEventListener('change',e=>{if(e.target.dataset.language){languageUI[e.target.dataset.language]=e.target.value;render()}if(e.target.hasAttribute('data-record-language')){recordUI.language=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){recordUI.query=e.target.value;document.querySelector('#document-results').innerHTML=recordCards()}});
function recordPlainText(){const r=activeRecord();if(!r)return '';const parts=[r.title,r.date];if(recordUI.tab!=='transcript'){const documentText=document.querySelector('.document-scroll')?.innerText;if(documentText)parts.push(documentText)}parts.push('原文与翻译',...r.lines.map(x=>`${clockText(x.time)} ${x.speaker||'说话人 1'}\n${x.en}\n${x.zh}`));return parts.join('\n\n')}
function exportRecord(){const r=activeRecord(),url=URL.createObjectURL(new Blob([recordPlainText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=r.title.replace(/[<>:"/\\|?*]/g,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyRecord(){try{await navigator.clipboard.writeText(recordPlainText());toast('文档已复制')}catch{toast('无法复制，请使用导出')}}
function highlightTranscript(value){const q=recordUI.transcriptQuery.trim();if(!q)return esc(value);let result='',cursor=0,pos;while((pos=value.toLowerCase().indexOf(q.toLowerCase(),cursor))!==-1){result+=esc(value.slice(cursor,pos))+'<mark>'+esc(value.slice(pos,pos+q.length))+'</mark>';cursor=pos+q.length}return result+esc(value.slice(cursor))}
function filterTranscript(){const r=activeRecord();if(!r)return;const q=recordUI.transcriptQuery.trim().toLowerCase();let count=0;document.querySelectorAll('#detail-transcript .transcript-paragraph').forEach(el=>{const i=Number(el.id.replace('source-','')),x=r.lines[i];const found=!q||(x.en+' '+x.zh).toLowerCase().includes(q);el.hidden=!found;if(found)count++;const en=el.querySelector('.original-text'),zh=el.querySelector('.translation-text');if(en)en.innerHTML=highlightTranscript(x.en);if(zh)zh.innerHTML=highlightTranscript(x.zh)});const counter=document.querySelector('#match-count');if(counter)counter.textContent=q?count+' 个匹配段落':''}
document.addEventListener('input',e=>{if(e.target.id==='transcript-search'){recordUI.transcriptQuery=e.target.value;filterTranscript()}});
let splitDrag=null;
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.split-handle')||e.button!==0)return;const handle=e.target.closest('.split-handle');splitDrag={handle,id:e.pointerId};handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing-record')});
document.addEventListener('pointermove',e=>{if(!splitDrag||e.pointerId!==splitDrag.id)return;const desk=document.querySelector('.record-desk'),r=desk.getBoundingClientRect();recordUI.split=Math.max(32,Math.min(62,Math.round((e.clientX-r.left)/r.width*100)));desk.style.setProperty('--doc-width',recordUI.split+'%');splitDrag.handle.setAttribute('aria-valuenow',recordUI.split)});
function stopSplit(){splitDrag=null;document.body.classList.remove('resizing-record')}
document.addEventListener('pointerup',stopSplit);document.addEventListener('pointercancel',stopSplit);
document.addEventListener('keydown',e=>{if(!e.target.matches('.split-handle')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();recordUI.split=Math.max(32,Math.min(62,recordUI.split+(e.key==='ArrowRight'?2:-2)));document.querySelector('.record-desk').style.setProperty('--doc-width',recordUI.split+'%');e.target.setAttribute('aria-valuenow',recordUI.split)});
